// Fork of "Sunlit Cave Falls" by wyatt. https://shadertoy.com/view/MfyBRK
// 2025-01-16 21:05:01

Main {
   R = iResolution.xy;
   vec4 q = B(U);
   Q = .5*A(U).w*(
       sin(-2.+.01*B(U).z+vec4(1,2,3,4))
   );
 }

vec2 R;
#define Main void mainImage(out vec4 Q, in vec2 U)

#define A(U) texelFetch(iChannel0,ivec2(U),0)
#define B(U) texelFetch(iChannel1,ivec2(U),0)
#define C(U) texture(iChannel2,(U)/R)
#define D(U) texture(iChannel3,(U)/R)

#define vel(v) (.5*v)*inversesqrt(1.+dot(v,v))

#define inside(v) ((v).x>=0.&&(v).y>=0.&&(v).x<R.x&&(v).y<R.y)

float ln (vec3 p, vec3 a, vec3 b) { 
    return length(p-a-(b-a)*(dot(p-a,b-a)/dot(b-a,b-a)));
}

bool scene (vec2 U) {
    if (U.x<1.||R.x-U.x<1.||U.y<1.) return false;
   return true;

}
vec4 hash(vec4 p4)
{
	p4 = fract(p4  * vec4(.1031, .1030, .0973, .1099));
    p4 += dot(p4, p4.wzxy+33.33);
    return fract((p4.xxyz+p4.yzzw)*p4.zywx);
}

Main {
    R = iResolution.xy;
    Q = A(U);
    vec4 T = Q;
    Q.z += B(U).w;
    Q.w += .1*B(U).w;
    for (int x = -1; x <= 1; x++)
    for (int y = -1; y <= 1; y++)
    if (x!=0||y!=0) {

        vec2 u = vec2(x,y);
        vec4 a = A(U+u);
        float f = .05*(a.w*(a.w-exp(-.1*a.z)));
        Q.xy -= f*u.xy;
        Q.z  -= Q.w*f*dot(a.xy-T.xy+u.xy,u.xy); 
    }
    Q.y -= .25/R.y;
    Q.z = max(Q.z,0.);
    if (length(Q.xy)>1.) Q.xy = normalize(Q.xy);
    if (Q.w>5.||Q.w<0.) Q.w = 5.;
    if (iFrame < 1) {

        Q = vec4(0,0,0,1);

    }
    if (!scene(U)) Q.z *= 0.;



    if (iMouse.z>0.&&length(U-iMouse.xy)< 10.) Q.w = 1.,Q.x = .5,Q.z=.8;
}

Main {

    R = iResolution.xy;
Q = A(U);
vec4 dQ = vec4(0);
#define K (1./8.)
for (int x = -1; x <= 1; x++)
for (int y = -1; y <= 1; y++)
if (x!=0||y!=0) {
    vec2 v = vec2(x,y);
    vec2 W = U+v;
    vec4 q = A(W);

    vec2 a = vel(Q.xy),
         b = vel(q.xy)+v;
    float ab = dot(v,b-a);
    if (scene(W)) {
        float i = dot(v,(0.5*v-a))/ab;
        float j = .5+.1*clamp(Q.w-q.w,0.05,1.);
        float k = .5+.1*clamp(q.w-Q.w,0.05,1.);
        float wa = K*Q.w*min(i,j)/j;
        float wb = K*q.w*max(k+i-1.,0.)/k;
        dQ += vec4(Q.xyz,1)*wa+vec4(q.xyz,1)*wb;
    } else {
        dQ += K*Q.w*vec4(Q.xyz,1);
    }

}
if (dQ.w>0.) dQ.xyz /= dQ.w;
Q = dQ;
}

Main {
    R = iResolution.xy;
    Q = A(U);
    Q.w = .05*B(U).z*B(U).w*Q.x*Q.y;
    Q.z += Q.w;
    Q.xy -= .005*Q.w;
    if (iFrame < 1) {
        Q = vec4(0);

        if (length(U-vec2(.5,.2)*R) < .1*R.y) Q.x = 10.;
        else Q.y = 1.;
        Q.y += 1.;
    }
}

Main {

    R = iResolution.xy;
Q = A(U);
vec4 dQ = vec4(0);
vec4 _ = B(U);
vec4 d_ = vec4(0);
#define K (1./8.)
for (int x = -1; x <= 1; x++)
for (int y = -1; y <= 1; y++)
if (x!=0||y!=0) {
    vec2 v = vec2(x,y);
    vec2 W = U+v;
    vec4 q = A(W);
    vec4 c = B(W);
    vec2 a = vel(Q.xy),
         b = vel(q.xy)+v;
    float ab = dot(v,b-a);
    if (scene(W)) {
        float i = dot(v,(0.5*v-a))/ab;
        float j = .5+.0*clamp(Q.w-q.w,0.05,1.);
        float k = .5+.0*clamp(q.w-Q.w,0.05,1.);
        float wa = K*Q.w*min(i,j)/j;
        float wb = K*q.w*max(k+i-1.,0.)/k;
        dQ += vec4(Q.xyz,1)*wa+vec4(q.xyz,1)*wb;
        d_ += _*wa+c*wb;
    } else {
        dQ += K*Q.w*vec4(Q.xyz,1);
        d_ += K*Q.w*_;
    }

}
if (dQ.w>0.) d_.xyz /= dQ.w;
Q = d_;
}
